// tongTien = "total amount", gio = "cart", apGiamGia = "apply discount", phiGiao = "delivery fee",
// kiemTraDon = "check order", boThu = "test suite", don = "order", ten = "name", sdt = "phone"
const MENU = { "ca-phe-den": 25000, "ca-phe-sua": 29000, "tra-dao": 34500, "banh-mi": 20000 };

function tongTien(gio) {
  let tong = 0;
  for (const dong of gio) tong += MENU[dong.mon] * dong.soLuong;
  return tong;
}

function apGiamGia(tong, ma) {
  if (ma === "GIAM10" && tong >= 100000) return tong - tong / 10;
  return tong;
}

function phiGiao(tong) {
  if (tong < 0) return "invalid total";
  if (tong >= 500000) return 0;
  return 30000;
}

// Function written by the AI. The test suite shows where it is wrong.
function kiemTraDon(don) {
  if (!don.ten) return "missing name";
  if (!/^0\d{9}$/.test(don.sdt)) return "invalid phone number";
  if (don.gio < 7 || don.gio >= 21) return "outside order hours";
  return "ok";
}

const boThu = [
  ["normal order", { ten: "An", sdt: "0901234567", gio: 9 }, "ok"],
  ["exactly 7:00", { ten: "An", sdt: "0901234567", gio: 7 }, "ok"],
  ["exactly 21:00", { ten: "An", sdt: "0901234567", gio: 21 }, "ok"],
  ["22:00", { ten: "An", sdt: "0901234567", gio: 22 }, "outside order hours"],
  ["name is only spaces", { ten: "   ", sdt: "0901234567", gio: 9 }, "missing name"],
  ["phone with 9 digits", { ten: "An", sdt: "090123456", gio: 9 }, "invalid phone number"],
];

let qua = 0;
for (const [ten, don, mong] of boThu) {
  const that = kiemTraDon(don);
  if (that === mong) qua++;
  else console.log("✗ " + ten + ": got \"" + that + "\", expected \"" + mong + "\"");
}
console.log("Passed " + qua + "/" + boThu.length);

// ---- Check that the finished functions were not changed; nothing to fix here ----
const nguyenVen =
  tongTien([{ mon: "tra-dao", soLuong: 1 }]) === 34500 &&
  apGiamGia(100000, "GIAM10") === 90000 &&
  phiGiao(500000) === 0;
console.log("Finished functions still intact: " + (nguyenVen ? "yes" : "no"));

